// Bundle all TSN compiler modules into a single file
// This creates a "fat" version that v1 can compile

const fs = require('fs');
const path = require('path');

const BASE_DIR = __dirname;

// Files to bundle in dependency order
const FILES = [
    'ast.tsn',
    'mir-flat.tsn', 
    'lexer.tsn',
    'ast-parser.tsn',
    'mir-builder-flat.tsn',
    'mir-codegen-flat.tsn',
    'main.tsn'
];

function stripImports(content) {
    // Remove import statements (including multi-line imports)
    return content.replace(/import\s+[\s\S]*?from\s+["'][^"']+["']\s*;/g, '');
}

function stripExports(content) {
    // Remove export keywords but keep class/function/enum/interface
    return content.replace(/export\s+(class|function|interface|enum)/g, '$1');
}

function removeExportBlocks(content) {
    // Remove standalone export { ... } statements (can be multi-line)
    return content.replace(/export\s*\{[^}]*\}/gs, '');
}

function removeDuplicateDeclarations(content) {
    // Remove duplicate declare statements
    const lines = content.split('\n');
    const seen = new Set();
    return lines.filter(line => {
        const trimmed = line.trim();
        if (trimmed.startsWith('declare function') || trimmed.startsWith('declare class')) {
            if (seen.has(trimmed)) {
                return false;
            }
            seen.add(trimmed);
        }
        return true;
    }).join('\n');
}

function processFile(filename) {
    const filepath = path.join(BASE_DIR, filename);
    const content = fs.readFileSync(filepath, 'utf8');
    
    let processed = stripImports(content);
    processed = stripExports(processed);
    processed = removeExportBlocks(processed);
    processed = removeDuplicateDeclarations(processed);
    
    return `// ===== From ${filename} =====\n\n${processed}\n\n`;
}

// Bundle all files
let bundled = `// TSN Self-Hosting Compiler - Bundled Single File
// Generated by bundle-compiler.js
// This file contains all compiler modules inlined for bootstrap compilation

`;

// Add std library declarations that we need
bundled += `// Standard library declarations (from std:console, std:fs, std:os)
declare function print_i32(n: i32): void;
declare function tsn_strlen(s: ptr): i32;
declare function tsn_alloc(size: i64): ptr;
declare function tsn_memcpy(dest: ptr, src: ptr, n: i32): void;
declare function tsn_write_i32(addr: ptr, val: i32): void;
declare function tsn_get_argc(): i32;
declare function tsn_get_argv(index: i32): ptr;
declare function cstringToString(cstr: ptr): string;
declare function debug_log_i32(val: i32): void;
declare function debug_log_i64(val: i64): void;
declare function debug_log_ptr(ptr: ptr): void;

// Declare runtime functions used from std modules  
declare function _T_log_P_ptr(s: ptr): void;
declare function _T_readText_P_ptr(path: ptr): ptr;
declare function _T_writeText_P_ptr_ptr(path: ptr, content: ptr): i32;

// Forward declare Array class (from std:array)
declare class Array<T> {
    constructor();
    push(item: T): void;
    get(index: i32): T;
    length: i32;
}

`;

// Process each file
for (const file of FILES) {
    console.log(`Processing ${file}...`);
    bundled += processFile(file);
}

// Write output
const outputPath = path.join(BASE_DIR, 'compiler-bundled.tsn');
fs.writeFileSync(outputPath, bundled, 'utf8');

console.log(`\n✅ Bundled compiler written to: ${outputPath}`);
console.log(`   Total size: ${(bundled.length / 1024).toFixed(2)} KB`);
